# thread-scoped state: lives and dies with one visit
thread_state = {"thread_id": "t-42", "messages": [...]}

# user-scoped memory: outlives every thread this person ever opens
user_memory = {
    "user_id": "u-7",
    "facts": ["prefers dark mode", "timezone: IST"],
}
# tomorrow's brand-new thread still starts from user_memory

def user_key(user_id: str) -> str:
    return f"user:memory:{user_id}"   # stable across all sessions

def save_fact(store, user_id: str, fact: str):
    mem = store.get(user_key(user_id)) or {"facts": []}
    mem["facts"].append(fact)
    store.set(user_key(user_id), mem)
# thread/session ids change; the user key does not

def load_for(store, authenticated_user_id: str) -> dict:
    # NEVER accept a user_id from the model or client input;
    # use the authenticated identity so memory can't cross users
    mem = store.get(user_key(authenticated_user_id)) or {"facts": []}
    return mem

SENSITIVE = {"health", "payment", "government_id"}
def may_store(category: str, consented: bool) -> bool:
    return consented and category not in SENSITIVE

