STORE = {}  # user_key -> {"facts": [...]}

def user_key(user_id: str) -> str:
    return f"user:memory:{user_id}"

def remember(user_id: str, fact: str) -> None:
    mem = STORE.setdefault(user_key(user_id), {"facts": []})
    mem["facts"].append(fact)

def start_session(user_id: str) -> str:
    mem = STORE.get(user_key(user_id))
    if mem and mem["facts"]:
        return "Known: " + "; ".join(mem["facts"])
    return "New user, no memory yet."

# session 1 for user u-7 teaches a preference
remember("u-7", "prefers dark mode")

# a brand-new session later still knows u-7
print(start_session("u-7"))

# a different user shares nothing
print(start_session("u-9"))

